import type { Metadata } from "next";
import { SITE_NAME } from "./site-config";

export const OG_LOCALE = "en_AE";
/** Routes generated by app/opengraph-image.tsx and app/twitter-image.tsx. */
export const OG_IMAGE_PATH = "/opengraph-image";
export const TWITTER_IMAGE_PATH = "/twitter-image";

type PageSeo = {
  /** Path from the site root, e.g. "/help". Use "/" for home. */
  path: string;
  title: string;
  description: string;
};

/**
 * One place for per-page SEO metadata: canonical, Open Graph and Twitter.
 * Next replaces (does not merge) nested `openGraph` objects, so every page
 * sets the full set here. Relative URLs resolve against `metadataBase`.
 */
export function pageMetadata({ path, title, description }: PageSeo): Metadata {
  return {
    title,
    description,
    alternates: { canonical: path },
    openGraph: {
      type: "website",
      siteName: SITE_NAME,
      locale: OG_LOCALE,
      title,
      description,
      url: path,
      images: [OG_IMAGE_PATH],
    },
    twitter: {
      card: "summary_large_image",
      title,
      description,
      images: [TWITTER_IMAGE_PATH],
    },
  };
}
